package com.hongguotv.core

internal object PhoneSearchPage {
    val styles="""
        :root{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC","Microsoft YaHei",sans-serif;color:#292832;background:#f7f5f2;color-scheme:light;--accent:#e95841;--muted:#8c8783}
        *{box-sizing:border-box}body{margin:0;padding:28px 18px max(28px,env(safe-area-inset-bottom));background:radial-gradient(ellipse at 90% 0,#ffe5d6,transparent 50%),#f7f5f2;min-height:100svh}button,input,select{font:inherit}button{cursor:pointer;touch-action:manipulation}button:disabled{opacity:.45;cursor:default}button:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #f6b4a3;outline-offset:2px}button{border:1px solid #eae5e0;background:#fff;border-radius:12px;min-height:42px;padding:9px 13px;color:inherit}button.selected,.primary{background:var(--accent);color:#fff;border-color:var(--accent)}[hidden]{display:none!important}.layout{max-width:1200px;margin:auto;display:flex;align-items:flex-start;gap:24px}.page{min-width:0;flex:1}.brand{display:flex;gap:10px;align-items:center;margin:0 0 18px;font-size:21px;font-weight:750}.logo{display:grid;place-items:center;width:37px;height:37px;border-radius:12px;background:var(--accent);color:#fff}.brand small{margin-left:auto;font-size:12px;color:var(--muted);font-weight:400}.card{background:#fff;border:1px solid #ebe5df;border-radius:24px;padding:24px;box-shadow:0 10px 36px #49302205}h1{font-size:25px;margin:4px 0 10px}h2{font-size:19px;margin:0}p{line-height:1.7}.intro,.muted{color:var(--muted);font-size:13px}.intro{margin:0 0 18px}.tabs,.genres{display:flex;gap:7px;flex-wrap:wrap;margin-bottom:18px}.tabs button{flex:1;white-space:nowrap;border:0;background:#eeebe7}.tabs button.selected{color:#fff;background:#292832}.genres button{flex:1}.options{display:flex;gap:12px;margin-bottom:16px}.option{flex:1;cursor:pointer;font-size:14px;padding:12px;background:#f8f6f3;border-radius:12px}.option input{accent-color:var(--accent);margin-right:8px}#query{width:100%;min-width:0;padding:14px;border:1px solid #e4ddd6;border-radius:12px;font-size:16px;background:#fdfcfb;margin:8px 0 12px}.submit{width:100%;font-weight:650}label{font-size:13px}#filters{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin:0 0 18px}#filters label{min-width:0;color:var(--muted)}select{display:block;width:100%;min-width:0;max-width:100%;border:1px solid #e7e1db;border-radius:9px;background:#faf9f7;color:#292832;padding:10px;margin-top:5px;font-size:13px}.result-top{display:flex;justify-content:space-between;align-items:center;gap:10px;margin:24px 0 14px}#list-state{font-size:13px;color:var(--muted);line-height:1.7;overflow-wrap:anywhere}.results{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px 12px}.series{min-width:0}.poster{aspect-ratio:3/4;background:#f0ede8;border-radius:12px;overflow:hidden;margin-bottom:9px}.poster img{width:100%;height:100%;object-fit:cover}.poster-fallback{display:grid;place-items:center;color:#b9aea7;font-size:12px;letter-spacing:.08em}.series h3{font-size:14px;line-height:1.5;margin:0 0 5px;overflow-wrap:anywhere;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;min-height:42px}.series p{font-size:11px;color:var(--muted);margin:2px 0;overflow-wrap:anywhere}.series .play{width:100%;font-size:12px;min-height:36px;padding:7px 4px;margin-top:8px;background:#fff0e9;color:#bd4933;border:0}.series .save{width:100%;font-size:11px;min-height:30px;border:0;background:transparent;padding:5px}.paging{display:flex;align-items:center;justify-content:center;gap:16px;margin-top:22px;font-size:13px}.footer{text-align:center;color:var(--muted);font-size:12px;line-height:1.8;margin:24px 0}.tv-panel{display:none;width:320px;flex:0 0 320px;position:sticky;top:24px;background:#fff;border:1px solid #ebe5df;border-radius:24px;padding:22px;max-height:calc(100vh - 48px);overflow:auto}.tv-panel.open{display:block}.tv-panel-top{display:flex;align-items:center;justify-content:space-between;margin-bottom:15px}.tv-caption{font-size:12px;color:var(--muted);margin:0}.panel-close{padding:7px 9px;font-size:12px;min-height:34px}.tv-now{padding:16px;border-radius:15px;background:#fff3ed}.tv-title{font-size:16px;font-weight:700;line-height:1.6;overflow-wrap:anywhere}.tv-episode{font-size:13px;margin-top:6px;color:#b0523d}.tv-state{font-size:12px;margin-top:8px;color:#8c736a}.progress{height:4px;background:#eadbd3;border-radius:3px;overflow:hidden;margin-top:13px}.progress i{display:block;height:100%;background:var(--accent);width:0}.time{font-size:11px;color:var(--muted);margin-top:6px}.transport{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:7px;margin-top:15px}.transport button{padding:8px 3px;font-size:12px}.tools{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:12px 0}.tools button{font-size:12px}.speed-label{font-size:12px;color:var(--muted);display:flex;gap:8px;align-items:center}.speed-label select{margin:0;flex:1}.tv-episodes-title{font-size:13px;font-weight:600;margin:20px 0 10px}.episode-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:6px;max-height:270px;overflow:auto;margin-top:9px}.episode{font-size:12px;padding:6px;min-height:36px;background:#faf8f6}.episode.current{border-color:var(--accent);color:var(--accent);background:#fff0e9}.tv-pending{font-size:12px;line-height:1.7;margin-top:12px;color:#a14c36;overflow-wrap:anywhere}.season-list{margin-top:18px;border-top:1px solid #eee4de;padding-top:15px}.season-list button{display:block;width:100%;text-align:left;font-size:12px;margin-top:7px}.filter-summary{font-size:12px;color:var(--muted);margin:0 0 12px}.filter-toggle{position:fixed;right:0;top:calc(44% - 102px);z-index:9;writing-mode:vertical-rl;background:#292832;color:#fff;border:0;border-radius:14px 0 0 14px;padding:16px 10px;font-size:13px;box-shadow:0 3px 15px #29283220}.filter-panel{width:min(410px,calc(100vw - 24px));max-height:calc(100svh - 32px);margin:auto 12px auto auto;padding:22px;border:1px solid #ebe5df;border-radius:22px;background:#fff;color:#292832;box-shadow:0 16px 48px #211b2426;overflow:hidden}.filter-panel[open]{display:flex;flex-direction:column}.filter-panel::backdrop{background:#211b2466}.filter-head{display:flex;gap:12px;justify-content:space-between;align-items:flex-start;margin-bottom:18px}.filter-head p{margin:7px 0 0}.filter-head button{font-size:12px;white-space:nowrap}.filter-panel #filters{overflow:auto;overscroll-behavior:contain;margin:0;padding:3px 3px 16px;flex:1;min-height:0;align-content:start}.filter-panel select{font-size:16px;min-height:46px}.filter-actions{display:flex;gap:10px;border-top:1px solid #eee6de;padding-top:16px}.filter-actions .primary{flex:1}.tv-toggle{display:none;position:fixed;right:0;top:44%;z-index:9;background:var(--accent);color:#fff;border:0;border-radius:14px 0 0 14px;writing-mode:vertical-rl;letter-spacing:1px;padding:14px 10px;font-size:12px;box-shadow:0 3px 15px #65311b20}.tv-toggle.live:before{content:'●';color:#b6f7b6;margin-bottom:6px}.tv-scrim{display:none}.toast{position:fixed;bottom:max(24px,env(safe-area-inset-bottom));left:50%;transform:translateX(-50%);max-width:calc(100vw - 30px);width:max-content;background:#292832;color:#fff;padding:12px 18px;border-radius:12px;font-size:13px;z-index:20;box-shadow:0 8px 30px #0002}
        @media(min-width:1100px){.results{grid-template-columns:repeat(4,minmax(0,1fr))}}@media(max-width:899px){.layout{max-width:660px}.tv-toggle{display:block}.tv-scrim.open{display:block;position:fixed;inset:0;z-index:10;background:#211b2466;border:0;border-radius:0}.tv-panel.open{position:fixed;z-index:11;top:0;bottom:0;right:0;max-height:100svh;width:min(360px,calc(100vw - 32px));border-radius:24px 0 0 24px;padding-top:max(24px,env(safe-area-inset-top));padding-bottom:max(24px,env(safe-area-inset-bottom))}}@media(max-width:379px){body{padding:20px 12px}.card{padding:18px 14px;border-radius:20px}.results{grid-template-columns:repeat(2,minmax(0,1fr))}.tabs{gap:4px}.tabs button{padding:9px 6px;font-size:12px}h1{font-size:26px}.brand small{font-size:11px}}
    """.trimIndent()
    fun render(submitPath: String,nonce: String,statusPath: String="/status",episodePath: String="/episode")="""
        <div class="layout" id="layout"><main class="page">
        <header class="brand"><span class="logo">▶</span>红果 TV<small id="connection">连接电视中</small></header>
        <section class="card"><h1>好故事，接着看。</h1><p class="intro">手机挑选，电视播放。你的大屏遥控就在这里。</p>
        <nav class="tabs" aria-label="内容导航"><button data-section="library" class="selected">剧库</button><button data-section="search">搜索</button><button data-section="history">最近观看</button><button data-section="favorites">收藏</button></nav>
        <div id="library-box"><div class="genres" aria-label="剧库分类"><button data-genre="comic_series" class="selected">漫剧</button><button data-genre="short_play">短剧</button><button data-genre="ai_series">AI 剧</button></div><p id="filter-summary" class="filter-summary" hidden></p></div>
        <form id="search-form" method="post" action="$submitPath" hidden><div class="options"><label class="option"><input type="radio" name="type" value="comic" checked>漫剧</label><label class="option"><input type="radio" name="type" value="short">短剧</label></div><label for="query">剧名或关键词</label><input id="query" name="query" maxlength="80" required placeholder="例如：修仙归来" autocomplete="off" enterkeyhint="search"><button class="primary submit" type="submit">在电视搜索 →</button><p class="muted">保留输入，结果会同步显示在下方。</p></form>
        <div class="result-top"><h2 id="list-heading">全部剧库</h2><button id="refresh-list" type="button">刷新</button></div><p id="list-state" role="status">正在读取内容…</p><div class="results" id="results"></div><div class="paging" id="paging" hidden><button id="previous-page">上一页</button><span id="page-number"></span><button id="next-page">下一页</button></div>
        </section><footer class="footer">手机与电视连接同一局域网 · 请保持电视应用运行</footer></main>
        <button class="tv-scrim" id="tv-scrim" aria-label="关闭电视遥控面板"></button><aside class="tv-panel" id="tv-panel" aria-label="电视播放控制"><div class="tv-panel-top"><p class="tv-caption">电视遥控</p><button class="panel-close" id="panel-close">收起 ×</button></div><div class="tv-now"><div class="tv-title" id="tv-title">等待电视播放</div><div class="tv-episode" id="tv-episode"></div><div class="tv-state" id="tv-state"></div><div class="progress"><i id="progress-fill"></i></div><div class="time" id="tv-time"></div></div>
        <div class="transport"><button data-action="previous">上一集</button><button id="pause-play" data-action="pause" class="primary">暂停</button><button data-action="next">下一集</button><button data-action="seek" data-value="-10">−10 秒</button><button data-action="retry" id="retry-play">重试播放</button><button data-action="seek" data-value="10">+10 秒</button></div><div class="tools"><button id="current-favorite">收藏本剧</button><button data-action="stop">退出播放</button><button data-action="home">电视首页</button></div><label class="speed-label">播放倍速<select id="playback-speed"><option value="0.75">0.75×</option><option value="1">1× 正常</option><option value="1.25">1.25×</option><option value="1.5">1.5×</option><option value="1.75">1.75×</option><option value="2">2×</option></select></label>
        <div id="episode-controls"><div class="tv-episodes-title">选择集数</div><select id="episode-group" aria-label="剧集分组"></select><div class="episode-grid" id="episode-grid"></div></div><div class="tv-pending" id="tv-pending" role="status"></div><div class="season-list" id="season-list" hidden></div></aside></div><button class="tv-toggle" id="tv-toggle" aria-controls="tv-panel" aria-expanded="false">TV 遥控</button>
        <button class="filter-toggle" id="filter-toggle" aria-controls="filter-panel" aria-expanded="false">筛选</button>
        <dialog class="filter-panel" id="filter-panel" aria-labelledby="filter-title"><div class="filter-head"><div><h2 id="filter-title">筛选剧库</h2><p id="filter-caption" class="muted"></p></div><button id="filter-close" aria-label="关闭筛选">关闭 ×</button></div><div id="filters"></div><div class="filter-actions"><button id="filter-reset">重置</button><button id="filter-apply" class="primary">查看结果</button></div></dialog>
        <script nonce="$nonce">
        const el=id=>document.getElementById(id);
        let section='library',genre='comic_series',filters={},filterDraft={},filterRows=[],snapshot=null,status={active:false},seasons=null;let panelOpen=false,groupIndex=0,groupKey='',waitingRevision=null,requestTicket=0,renderKey='',statusBusy=false,resultsBusy=false,pendingPlay=null,toastTimer=null,toastAfterResults=false,selectedSection=null,searchedQuery=null;
        const labels={library:'全部剧库',search:'搜索结果',history:'最近观看',favorites:'我的收藏',home:'热门推荐'};const stateNames={loading:'正在加载',buffering:'缓冲中',playing:'正在播放',paused:'已暂停',ended:'本集已结束',error:'播放失败',idle:'未在播放'};
        function browserImageUrl(value){if(!value)return '';try{const url=new URL(value,document.baseURI);if(/\.heic$/i.test(url.pathname))return 'https://images.weserv.nl/?url='+encodeURIComponent(value)+'&output=jpg';}catch(_){ }return value;}
        function appendPoster(poster,value){const source=browserImageUrl(value);if(!source){poster.classList.add('poster-fallback');poster.textContent='暂无海报';return;}const img=document.createElement('img');img.src=source;img.alt='';img.loading='lazy';img.referrerPolicy='no-referrer';img.onerror=()=>{img.remove();poster.classList.add('poster-fallback');poster.textContent='海报暂不可用';};poster.append(img);}
        function toast(text){let box=el('toast');if(!box){box=document.createElement('div');box.id='toast';box.className='toast';box.setAttribute('role','status');document.body.append(box);}box.textContent=text;clearTimeout(toastTimer);toastTimer=setTimeout(()=>box.remove(),3500);}
        async function api(path,data){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),5000);try{const response=await fetch(path,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/x-www-form-urlencoded','Accept':'application/json'}:{'Accept':'application/json'},body:data?new URLSearchParams(data):undefined,signal:controller.signal,cache:'no-store'});const result=await response.json();if(!response.ok)throw Error(result.message||'电视暂时无法处理，请重试');return result;}catch(error){if(error.name==='AbortError')throw Error('连接电视超时，请检查网络');throw error;}finally{clearTimeout(timer);}}
        function setSection(value){section=value;el('filter-toggle').hidden=value!=='library';if(value!=='library')setFilters(false);document.querySelectorAll('[data-section]').forEach(button=>button.classList.toggle('selected',button.dataset.section===value));el('library-box').hidden=value!=='library';el('search-form').hidden=value!=='search';el('list-heading').textContent=labels[value]||'搜索结果';}
        function clearResults(message){el('results').replaceChildren();el('paging').hidden=true;el('list-state').textContent=message;renderKey='';}
        async function requestList(path,data,message){const ticket=++requestTicket;waitingRevision=Number.MAX_SAFE_INTEGER;clearResults(message);try{const result=await api(path,data);if(ticket!==requestTicket)return;waitingRevision=result.revision;await refreshResults();}catch(error){if(ticket===requestTicket){waitingRevision=null;clearResults(error.message);toast(error.message);}}}
        async function browse(){if(section==='search'){if(el('query').value.trim())return search();requestTicket++;waitingRevision=null;snapshot=null;searchedQuery=null;clearResults('输入剧名，搜索结果会显示在这里。');return;}return requestList('/browse',section==='library'?{section:'library',genre,filters:JSON.stringify(filters)}:{section,type:'comic'},'正在读取'+labels[section]+'…');}
        async function search(){const query=el('query').value.trim();if(!query)return;searchedQuery=query;toastAfterResults=true;return requestList('$submitPath',{query,type:el('search-form').elements.type.value},'电视正在搜索，请稍候…');}
        el('search-form').addEventListener('submit',async event=>{event.preventDefault();const button=event.currentTarget.querySelector('button');button.disabled=true;try{await search();}finally{button.disabled=false;}});document.querySelectorAll('[data-section]').forEach(button=>button.onclick=()=>{selectedSection=button.dataset.section;setSection(selectedSection);browse();});
        document.querySelectorAll('[data-genre]').forEach(button=>button.onclick=()=>{genre=button.dataset.genre;filters={};filterRows=[];renderFilterSummary();el('filters').replaceChildren();document.querySelectorAll('[data-genre]').forEach(item=>item.classList.toggle('selected',item===button));browse();});el('refresh-list').onclick=()=>browse();
        function renderFilterSummary(){const count=Object.keys(filters).length;el('filter-toggle').textContent=count?'筛选 · '+count:'筛选';el('filter-summary').hidden=!count;el('filter-summary').textContent='已选 '+count+' 项条件 · 点击右侧筛选可修改';}
        function drawFilters(){el('filters').replaceChildren();el('filter-caption').textContent=({comic_series:'漫剧',short_play:'短剧',ai_series:'AI 剧'})[genre]+' · 选择后点击查看结果';filterRows.forEach(row=>{const label=document.createElement('label');label.textContent=row.label;const select=document.createElement('select');select.setAttribute('aria-label',row.label);row.options.forEach(option=>{const item=document.createElement('option');item.value=option.value;item.textContent=option.label;select.append(item);});select.value=filterDraft[row.key]||'';select.onchange=()=>{if(select.value)filterDraft[row.key]=select.value;else delete filterDraft[row.key];};label.append(select);el('filters').append(label);});if(!filterRows.length){const note=document.createElement('p');note.className='muted';note.textContent='分类正在加载，请稍候…';el('filters').append(note);}el('filter-apply').disabled=!filterRows.length;}
        function renderFilters(data){const wasEmpty=!filterRows.length;filterRows=data.filterRows||[];renderFilterSummary();if(el('filter-panel').open&&wasEmpty)drawFilters();}
        function setFilters(open){const panel=el('filter-panel');if(open){if(panel.open)return;filterDraft={...filters};drawFilters();setPanel(false);panel.showModal();}else if(panel.open)panel.close();el('filter-toggle').setAttribute('aria-expanded',String(panel.open));}
        el('filter-toggle').onclick=()=>setFilters(true);el('filter-close').onclick=()=>setFilters(false);el('filter-panel').addEventListener('close',()=>el('filter-toggle').setAttribute('aria-expanded','false'));el('filter-panel').addEventListener('click',event=>{if(event.target===event.currentTarget){const box=event.currentTarget.getBoundingClientRect();if(event.clientX<box.left||event.clientX>box.right||event.clientY<box.top||event.clientY>box.bottom)setFilters(false);}});el('filter-reset').onclick=()=>{filterDraft={};drawFilters();};el('filter-apply').onclick=()=>{filters={...filterDraft};renderFilterSummary();setFilters(false);browse();};
        function renderResults(data){if(selectedSection!==null&&(data.section!==section||section==='library'&&data.genre!==genre||section==='search'&&(!searchedQuery||data.query!==searchedQuery)))return;const key=JSON.stringify(data);if(key===renderKey)return;renderKey=key;snapshot=data;if(selectedSection===null)selectedSection=data.section==='home'?'library':data.section;setSection(selectedSection);genre=data.genre||genre;filters=data.filters||{};document.querySelectorAll('[data-genre]').forEach(button=>button.classList.toggle('selected',button.dataset.genre===genre));if(section==='library')renderFilters(data);el('results').replaceChildren();el('paging').hidden=true;el('list-state').textContent=data.loading?'正在加载，请稍候…':data.error||((data.items||[]).length? (data.section==='search'?'“'+data.query+'” · ':'')+'点击电视播放，可从上次观看处继续。':'暂时没有内容。');if(data.loading||data.error)return;(data.items||[]).forEach(item=>{const card=document.createElement('article');card.className='series';const poster=document.createElement('div');poster.className='poster';appendPoster(poster,item.cover);const heading=document.createElement('h3');heading.textContent=item.title;const info=document.createElement('p');info.textContent=item.badge||item.tags||'';const progress=document.createElement('p');progress.textContent=item.progress||' ';const play=document.createElement('button');play.className='play';play.textContent='电视播放 ▶';play.onclick=()=>playSeries(data.revision,item.id,play);const save=document.createElement('button');save.className='save';save.textContent=item.favorite?'♥ 已收藏':'♡ 收藏';save.onclick=async()=>{save.disabled=true;try{await api('/favorite',{revision:data.revision,id:item.id,value:item.favorite?'0':'1'});await refreshResults();}catch(error){toast(error.message);}finally{save.disabled=false;}};card.append(poster,heading,info,progress,play,save);el('results').append(card);});el('paging').hidden=!(data.page>1||data.hasMore);el('previous-page').disabled=data.page<=1;el('next-page').disabled=!data.hasMore;el('page-number').textContent='第 '+data.page+' 页';}
        async function refreshResults(){if(resultsBusy)return;resultsBusy=true;const ticket=requestTicket;try{const data=await api('/results');if(ticket!==requestTicket)return;if(waitingRevision!==null){if(data.revision<=waitingRevision)return;waitingRevision=null;}renderResults(data);if(toastAfterResults&&!data.loading){toastAfterResults=false;toast(data.error||'已在 TV 搜索，请查看结果');}}catch(error){el('connection').textContent='连接已中断';clearResults('无法连接电视，请检查网络后刷新。');}finally{resultsBusy=false;}}
        async function turnPage(delta){if(!snapshot||snapshot.loading)return;return requestList('/search-page',{revision:snapshot.revision,page:snapshot.page+delta},'正在翻页…');}el('previous-page').onclick=()=>turnPage(-1);el('next-page').onclick=()=>turnPage(1);
        async function playSeries(revision,id,button,path='/play'){button.disabled=true;pendingPlay={id,session:status.session||0,time:Date.now()};el('tv-pending').textContent='正在通知电视加载…';setPanel(true);try{await api(path,{revision,id});toast('已发送点播，等待电视加载');await refreshStatus();}catch(error){pendingPlay=null;toast(error.message);}finally{button.disabled=false;}}
        function setPanel(open){panelOpen=!!open;const wide=window.matchMedia('(min-width:900px)').matches;const show=status.active&&(panelOpen||wide);el('tv-panel').classList.toggle('open',show);el('tv-scrim').classList.toggle('open',show&&!wide);el('tv-toggle').setAttribute('aria-expanded',String(show));}el('tv-toggle').onclick=()=>setPanel(!panelOpen);el('panel-close').onclick=()=>setPanel(false);el('tv-scrim').onclick=()=>setPanel(false);window.addEventListener('resize',()=>setPanel(panelOpen));
        function time(ms){const seconds=Math.floor(Math.max(0,ms||0)/1000);return Math.floor(seconds/60)+':'+String(seconds%60).padStart(2,'0');}
        function renderEpisodes(){const count=status.episodeCount||0;el('episode-grid').replaceChildren();const start=groupIndex*50;for(let index=start;index<Math.min(start+50,count);index++){const button=document.createElement('button');button.className='episode'+(index+1===status.episode?' current':'');button.textContent=index+1;button.setAttribute('aria-label','播放第 '+(index+1)+' 集');button.onclick=async()=>{button.disabled=true;try{await api('$episodePath',{episode:index+1,key:status.key});el('tv-pending').textContent='正在切换到第 '+(index+1)+' 集';}catch(error){toast(error.message);}finally{button.disabled=false;}};el('episode-grid').append(button);}}el('episode-group').onchange=event=>{groupIndex=Number(event.target.value);renderEpisodes();};
        function renderStatus(data){const previous=status;status=data;el('connection').textContent='已连接电视';el('tv-toggle').style.display=data.active?'':'none';el('tv-toggle').classList.toggle('live',data.active&&data.playing);el('tv-toggle').textContent='TV '+(stateNames[data.state]||'遥控');el('tv-title').textContent=data.active?data.title:'等待电视播放';el('tv-episode').textContent=data.active&&data.episodeCount?'第 '+data.episode+' 集 / 共 '+data.episodeCount+' 集':'';el('tv-state').textContent=data.error||stateNames[data.state]||'';el('progress-fill').style.width=(data.duration?Math.min(100,data.position/data.duration*100):0)+'%';el('tv-time').textContent=data.active?time(data.position)+' / '+time(data.duration):'';el('pause-play').textContent=data.playing?'暂停':'继续';el('pause-play').dataset.action=data.playing?'pause':'play';el('retry-play').disabled=data.state!=='error';el('current-favorite').textContent=data.favorite?'♥ 已收藏':'♡ 收藏本剧';el('playback-speed').value=String(data.speed||1);el('episode-controls').hidden=!data.active||!data.episodeCount;const key=data.active?data.key+'/'+data.episodeCount:'';if(key!==groupKey){groupKey=key;groupIndex=Math.floor(Math.max(0,(data.episode||1)-1)/50);el('episode-group').replaceChildren();for(let index=0;index<Math.ceil((data.episodeCount||0)/50);index++){const option=document.createElement('option');option.value=index;option.textContent=(index*50+1)+'—'+Math.min((index+1)*50,data.episodeCount)+' 集';el('episode-group').append(option);}el('episode-group').value=String(groupIndex);renderEpisodes();}else if(previous.episode!==data.episode)renderEpisodes();document.querySelectorAll('[data-action]').forEach(button=>{const action=button.dataset.action;button.disabled=!data.active||action==='previous'&&data.episode<=1||action==='next'&&data.episode>=data.episodeCount||['play','pause','seek'].includes(action)&&['loading','error'].includes(data.state)||action==='seek'&&!data.duration||action==='retry'&&data.state!=='error';});if(pendingPlay){if(data.key===pendingPlay.id&&Number(data.session||0)!==pendingPlay.session){if(data.state==='playing'){pendingPlay=null;toast('电视已开始播放');el('tv-pending').textContent='电视已开始播放';}else if(data.state==='error'){pendingPlay=null;el('tv-pending').textContent=data.error||'播放失败，请重试';setPanel(true);}else el('tv-pending').textContent='电视'+(stateNames[data.state]||'正在响应')+'…';}if(pendingPlay&&Date.now()-pendingPlay.time>45000){pendingPlay=null;el('tv-pending').textContent='尚未确认播放，请检查电视状态或重试';toast('尚未确认播放，请检查电视');}}if(!data.active){el('episode-grid').replaceChildren();el('season-list').hidden=true;seasons=null;if(!pendingPlay)el('tv-pending').textContent='';setPanel(false);}else setPanel(panelOpen);}
        async function refreshStatus(){if(statusBusy)return;statusBusy=true;try{renderStatus(await api('$statusPath'));}catch(error){renderStatus({active:false,state:'idle'});el('connection').textContent='电视连接已中断';if(pendingPlay){pendingPlay=null;toast('连接已中断，尚未确认播放');}}finally{statusBusy=false;}}
        async function control(action,value=''){try{await api('/control',{action,key:['home','stop'].includes(action)?'':status.key||'',value});el('tv-pending').textContent='指令已发送，等待电视状态更新';await refreshStatus();}catch(error){toast(error.message);}}document.querySelectorAll('[data-action]').forEach(button=>button.onclick=()=>control(button.dataset.action,button.dataset.value||''));el('playback-speed').onchange=event=>control('speed',event.target.value);el('current-favorite').onclick=()=>control('favorite',status.favorite?'0':'1');
        async function refreshSeasons(){if(!status.active)return;try{const data=await api('/seasons');if(data.query!==status.title){el('season-list').hidden=true;return;}const key=JSON.stringify(data);if(seasons===key){el('season-list').hidden=false;return;}seasons=key;const box=el('season-list');box.replaceChildren();box.hidden=false;const title=document.createElement('h2');title.textContent='后续季';box.append(title);const note=document.createElement('p');note.className='muted';note.textContent=data.loading?'正在搜索后续季…':data.error||(data.items.length?'同名后续季候选，点击在电视续看':'暂未找到同名后续季');box.append(note);(data.items||[]).forEach(item=>{const button=document.createElement('button');button.textContent=item.title;button.onclick=()=>playSeries(data.revision,item.id,button,'/season-play');box.append(button);});}catch(error){el('season-list').hidden=true;}}
        async function poll(){await refreshStatus();await refreshResults();await refreshSeasons();setTimeout(poll,1500);}browse();poll();
        </script>
    """.trimIndent()
